CREATE TABLE IF NOT EXISTS pve_regions (id BIGSERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', sort_order INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS pve_nodes (id BIGSERIAL PRIMARY KEY, region_id BIGINT NOT NULL REFERENCES pve_regions(id), name TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL DEFAULT 8006, cluster_name TEXT NOT NULL DEFAULT '', api_user TEXT NOT NULL, api_token_id TEXT NOT NULL, api_token_secret TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', last_checked_at BIGINT, last_error TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS pve_instance_flavors (id BIGSERIAL PRIMARY KEY, instance_flavor_code TEXT NOT NULL, name TEXT NOT NULL, cpu_cores INTEGER NOT NULL, memory_gb INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', sort_order INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE(cpu_cores, memory_gb));
CREATE TABLE IF NOT EXISTS pve_vms (id BIGSERIAL PRIMARY KEY, kind TEXT NOT NULL DEFAULT 'qemu', region_id BIGINT NOT NULL REFERENCES pve_regions(id), node_id BIGINT NOT NULL REFERENCES pve_nodes(id), instance_flavor_id BIGINT NOT NULL REFERENCES pve_instance_flavors(id), name TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'allocating', pve_status TEXT NOT NULL DEFAULT '', pve_config JSONB NOT NULL DEFAULT '{}'::jsonb, error_message TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, deleted_at BIGINT);
CREATE TABLE IF NOT EXISTS pve_vm_tasks (id BIGSERIAL PRIMARY KEY, vm_id BIGINT NOT NULL REFERENCES pve_vms(id), action TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', request_payload JSONB NOT NULL DEFAULT '{}'::jsonb, response_payload JSONB NOT NULL DEFAULT '{}'::jsonb, retry_count INTEGER NOT NULL DEFAULT 0, error_message TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
